DO $$ DECLARE definition text; BEGIN SELECT pg_get_functiondef('public.pos_expedition_transition(jsonb,text,text,jsonb,jsonb,timestamptz)'::regprocedure) INTO definition; definition:=replace(definition,'SELECT actual.sale_id,actual.id,actual.barcode,','SELECT check_item.sale_id,check_item.id,check_item.barcode,'); definition:=replace(definition,'JOIN public.pos_sale_items actual ON actual.id=','JOIN public.pos_sale_items check_item ON check_item.id='); EXECUTE definition; END; $$;